edges = [(2,7), (0,5), (1,4), (3,6)]
print("Edges:", edges)
print("Sorted:", sorted(edges))

# Verify all constraints
from collections import defaultdict
adj = defaultdict(set)
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

print("\nDegrees:")
for v in range(8):
    print(f"  Vertex {v}: degree {len(adj[v])}")

print("\nAll degrees >= 1:", all(len(adj[v]) >= 1 for v in range(8)))

# Check bipartite
color = [-1]*8
def dfs(u, c):
    color[u] = c
    for v in adj[u]:
        if color[v] == -1:
            if not dfs(v, 1-c):
                return False
        elif color[v] == c:
            return False
    return True

bip = True
for v in range(8):
    if color[v] == -1:
        if not dfs(v, 0):
            bip = False
            break
print("Bipartite:", bip)
print("Colors:", color)

# Max clique
import itertools
n=8
adj_mat = [[False]*n for _ in range(n)]
for u,v in edges:
    adj_mat[u][v] = adj_mat[v][u] = True

max_clique = 0
for r in range(1, n+1):
    for combo in itertools.combinations(range(n), r):
        ok = True
        for i in range(r):
            for j in range(i+1, r):
                if not adj_mat[combo[i]][combo[j]]:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            max_clique = max(max_clique, r)
print("Max clique size:", max_clique)
print("Max clique <= 4:", max_clique <= 4)
